<?php
declare(strict_types=1);ob_start();session_start();require dirname(__DIR__,2).'/config/config.php';
function rc_json(int $status,array $data):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(ob_get_level())ob_clean();echo json_encode($data,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
function rc_ok(string $message,array $data=[]):never{rc_json(200,['ok'=>true,'message'=>$message,'data'=>$data]);}
if(!signed_in())rc_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);require_sign_in();if(!empty($_SESSION['must_change_password']))rc_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);
$db=db();$uid=(int)$_SESSION['user_id'];$role=(string)$_SESSION['role'];$school=filter_var($_REQUEST['school_id']??null,FILTER_VALIDATE_INT);$examId=filter_var($_REQUEST['exam_id']??null,FILTER_VALIDATE_INT);if(!$school||!$examId)rc_json(422,['ok'=>false,'message'=>'Choose a school and examination.']);
$member=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$member->execute([$uid,$school]);if(!$member->fetchColumn())rc_json(403,['ok'=>false,'message'=>'That school is outside your access.']);
$requestRoles=['teacher','assistant_academic','head_academic','examination_officer','headteacher','sub_director','director'];$reviewRoles=['director','sub_director','headteacher','head_academic','examination_officer'];$canRequest=in_array($role,$requestRoles,true);$canReview=in_array($role,$reviewRoles,true);
function rc_audit(PDO $db,int $uid,string $action,string $entity,int $id,array $details):void{$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,$action,$entity,$id,json_encode($details,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE)]);}
function rc_exam(PDO $db,int $exam,int $school,bool $lock=false):array|false{$q=$db->prepare('SELECT * FROM school_exams WHERE id=? AND school_id=?'.($lock?' FOR UPDATE':''));$q->execute([$exam,$school]);return $q->fetch();}
function rc_teacher_scope(PDO $db,int $uid,int $school,int $year,string $class,string $subject):bool{$q=$db->prepare('SELECT 1 FROM teacher_assignments WHERE user_id=? AND school_id=? AND class_level=? AND subject=? AND active=1 UNION SELECT 1 FROM result_delegations WHERE user_id=? AND school_id=? AND active=1 AND academic_year=? AND (class_level IS NULL OR class_level=?) LIMIT 1');$q->execute([$uid,$school,$class,$subject,$uid,$school,$year,$class]);return(bool)$q->fetch();}
if($_SERVER['REQUEST_METHOD']==='GET'){
 if(!$canRequest&&!$canReview)rc_json(403,['ok'=>false,'message'=>'Your role cannot view result correction requests.']);$exam=rc_exam($db,(int)$examId,(int)$school);if(!$exam||$exam['status']!=='results_published')rc_json(404,['ok'=>false,'message'=>'Published examination not found.']);
 $sql='SELECT q.id,q.pupil_result_id,q.original_score,q.requested_score,q.reason,q.status,q.requested_by,q.reviewed_by,q.review_note,q.reviewed_at,q.created_at,r.assessment,r.subject,r.class_level,r.max_score,p.first_name,p.middle_name,p.last_name,requester.name requester_name,reviewer.name reviewer_name FROM result_correction_requests q JOIN pupil_results r ON r.id=q.pupil_result_id AND r.school_id=q.school_id JOIN pupils p ON p.id=r.pupil_id AND p.school_id=r.school_id JOIN users requester ON requester.id=q.requested_by LEFT JOIN users reviewer ON reviewer.id=q.reviewed_by WHERE q.school_id=? AND q.exam_id=?';$params=[$school,$examId];if(!$canReview){$sql.=' AND q.requested_by=?';$params[]=$uid;}$sql.=" ORDER BY FIELD(q.status,'pending','approved','rejected'),q.created_at DESC LIMIT 300";$q=$db->prepare($sql);$q->execute($params);rc_ok('Correction requests loaded.',['requests'=>$q->fetchAll(),'can_review'=>$canReview,'user_id'=>$uid]);
}
if($_SERVER['REQUEST_METHOD']!=='POST')rc_json(405,['ok'=>false,'message'=>'Method not allowed.']);if(!hash_equals($_SESSION['csrf']??'',(string)($_SERVER['HTTP_X_CSRF_TOKEN']??$_POST['csrf']??'')))rc_json(400,['ok'=>false,'message'=>'Your session expired. Refresh and try again.']);$action=(string)($_POST['action']??'');
if($action==='request'){
 if(!$canRequest)rc_json(403,['ok'=>false,'message'=>'Your role cannot request result corrections.']);$resultId=filter_var($_POST['result_id']??null,FILTER_VALIDATE_INT);$requested=filter_var($_POST['requested_score']??null,FILTER_VALIDATE_FLOAT);$reason=trim((string)($_POST['reason']??''));if(!$resultId||$requested===false||$requested<0||mb_strlen($reason)<10||mb_strlen($reason)>2000)rc_json(422,['ok'=>false,'message'=>'Enter a valid replacement score and a correction reason of 10 to 2,000 characters.']);
 try{$db->beginTransaction();$exam=rc_exam($db,(int)$examId,(int)$school,true);if(!$exam||$exam['status']!=='results_published')throw new DomainException('Corrections can only be requested for published results.');$q=$db->prepare('SELECT r.id,r.school_id,r.exam_name,r.academic_year,r.class_level,r.subject,r.score,r.max_score,p.first_name,p.middle_name,p.last_name FROM pupil_results r JOIN pupils p ON p.id=r.pupil_id AND p.school_id=r.school_id WHERE r.id=? AND r.school_id=? AND r.exam_name=? AND r.academic_year=? FOR UPDATE');$q->execute([$resultId,$school,$exam['name'],$exam['academic_year']]);$result=$q->fetch();if(!$result)throw new DomainException('That result does not belong to this examination and school.');if($exam['class_id']){$q=$db->prepare('SELECT name FROM school_classes WHERE id=? AND school_id=?');$q->execute([$exam['class_id'],$school]);if($q->fetchColumn()!==$result['class_level'])throw new DomainException('That result is outside the examination class.');}if($exam['subject_id']){$q=$db->prepare('SELECT name FROM school_class_subjects WHERE id=?');$q->execute([$exam['subject_id']]);if($q->fetchColumn()!==$result['subject'])throw new DomainException('That result is outside the examination subject.');}if($role==='teacher'&&!rc_teacher_scope($db,$uid,(int)$school,(int)$exam['academic_year'],$result['class_level'],$result['subject']))throw new DomainException('You do not have editing access to this class and subject.');if(abs((float)$requested-round((float)$requested,2))>0.0001)throw new DomainException('Use a score with no more than two decimal places.');if($requested>(float)$result['max_score'])throw new DomainException('The replacement score cannot exceed the maximum shown.');if(abs((float)$result['score']-(float)$requested)<0.0001)throw new DomainException('The replacement score must differ from the published score.');$q=$db->prepare("SELECT id FROM result_correction_requests WHERE school_id=? AND pupil_result_id=? AND status='pending' LIMIT 1");$q->execute([$school,$resultId]);if($q->fetchColumn())throw new DomainException('A correction request is already pending for this result.');$q=$db->prepare("INSERT INTO result_correction_requests(school_id,exam_id,pupil_result_id,original_score,requested_score,reason,requested_by) VALUES(?,?,?,?,?,?,?)");$q->execute([$school,$examId,$resultId,$result['score'],$requested,$reason,$uid]);$requestId=(int)$db->lastInsertId();rc_audit($db,$uid,'request','result_correction_request',$requestId,['school_id'=>(int)$school,'exam_id'=>(int)$examId,'pupil_result_id'=>(int)$resultId,'original_score'=>(float)$result['score'],'requested_score'=>(float)$requested,'reason'=>$reason]);$db->commit();rc_ok('Correction request submitted for independent review.',['request_id'=>$requestId]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();rc_json($e instanceof DomainException?422:500,['ok'=>false,'message'=>$e instanceof DomainException?$e->getMessage():'The correction request could not be saved. Apply the result-correction migration and retry.']);}
}
if($action==='review'){
 if(!$canReview)rc_json(403,['ok'=>false,'message'=>'Your role cannot review result corrections.']);$requestId=filter_var($_POST['request_id']??null,FILTER_VALIDATE_INT);$decision=(string)($_POST['decision']??'');$note=trim((string)($_POST['review_note']??''));if(!$requestId||!in_array($decision,['approved','rejected'],true)||mb_strlen($note)>2000||($decision==='rejected'&&$note===''))rc_json(422,['ok'=>false,'message'=>'Choose approve or reject and provide a reason when rejecting.']);
 try{$db->beginTransaction();$q=$db->prepare('SELECT * FROM result_correction_requests WHERE id=? AND school_id=? AND exam_id=? FOR UPDATE');$q->execute([$requestId,$school,$examId]);$request=$q->fetch();if(!$request||$request['status']!=='pending')throw new DomainException('Only a pending correction request in this examination can be reviewed.');if((int)$request['requested_by']===$uid)throw new DomainException('A different authorized reviewer must decide this request.');$exam=rc_exam($db,(int)$examId,(int)$school,true);if(!$exam||$exam['status']!=='results_published')throw new DomainException('The examination is no longer available for correction.');$q=$db->prepare('SELECT score,max_score FROM pupil_results WHERE id=? AND school_id=? FOR UPDATE');$q->execute([$request['pupil_result_id'],$school]);$result=$q->fetch();if(!$result||(float)$result['score']!==(float)$request['original_score'])throw new DomainException('The published score changed since this request was created. Reconcile the record before making another correction.');if((float)$request['requested_score']>(float)$result['max_score'])throw new DomainException('The requested score exceeds the current maximum.');if($decision==='approved'){$db->prepare('UPDATE pupil_results SET score=? WHERE id=? AND school_id=?')->execute([$request['requested_score'],$request['pupil_result_id'],$school]);}$db->prepare('UPDATE result_correction_requests SET status=?,reviewed_by=?,review_note=?,reviewed_at=CURRENT_TIMESTAMP WHERE id=? AND school_id=?')->execute([$decision,$uid,$note?:null,$requestId,$school]);rc_audit($db,$uid,$decision,'result_correction_request',(int)$requestId,['school_id'=>(int)$school,'exam_id'=>(int)$examId,'pupil_result_id'=>(int)$request['pupil_result_id'],'original_score'=>(float)$request['original_score'],'requested_score'=>(float)$request['requested_score'],'review_note'=>$note]);if($decision==='approved')rc_audit($db,$uid,'correct','pupil_result',(int)$request['pupil_result_id'],['school_id'=>(int)$school,'exam_id'=>(int)$examId,'before'=>(float)$request['original_score'],'after'=>(float)$request['requested_score'],'correction_request_id'=>(int)$requestId]);$db->commit();rc_ok($decision==='approved'?'Correction approved; the published score and audit history were updated.':'Correction request rejected with a recorded reason.',['request_id'=>(int)$requestId,'status'=>$decision]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();rc_json($e instanceof DomainException?422:500,['ok'=>false,'message'=>$e instanceof DomainException?$e->getMessage():'The correction decision could not be saved.']);}
}
rc_json(422,['ok'=>false,'message'=>'Unknown correction action.']);
